uncache(Result) ->
    element(1, Result).

uncache_skewness(State) ->
    uncache(skewness(State)).

uncache_kurtosis(State) ->
    uncache(kurtosis(State)).

uncache_stddev(State) ->
    uncache(standard_deviation(State)).

normal_distribution_value([], _, _) ->
    [];
normal_distribution_value([Uniform1, Uniform2 | L], Mean, StandardDeviation) ->
    % use Box-Muller transformation to generate Gaussian noise
    %
    % George Edward Pelham Box, Mervin Edgar Muller.
    % A Note on the Generation of Random Normal Deviates.
    % The Annals of Mathematical Statistics,
    % vol. 29, no. 2, pp. 610–611, 1958.
    K = StandardDeviation * math:sqrt(-2.0 * math:log(Uniform1)),
    Radians = 2 * math:pi() * Uniform2,
    Normal1 = Mean + K * math:cos(Radians),
    Normal2 = Mean + K * math:sin(Radians),
    [Normal1, Normal2 | normal_distribution_value(L, Mean, StandardDeviation)].

normal_distribution() ->
    Mean = 0,
    StandardDeviation = 1.0,
    normal_distribution_value(random_value_list(), Mean, StandardDeviation).

t_random_value() ->
    L = random_value_list(),
    % standard deviation of a uniform distribution [a .. b]
    %   with a = 0.0 and b = 1.0 : ((b - a)^2 / 12)^0.5 = 0.288675...
    % skewness of a uniform distribution is 0.0
    % kurtosis of a discrete uniform distribution is -1.2
    StateX6 = add_from_list(L, new()),
    StateM6_1 = add_from_list(lists:sublist(L, 500000), new()),
    StateM6_2 = add_from_list(lists:sublist(L, 500001, 500000), new()),
    StateM6A = merge(StateM6_1, StateM6_2),
    StateM6B = merge(StateM6_2, StateM6_1),
    1000000 = count(StateX6),
    "9.99999e-01" = erlang:float_to_list(maximum(StateX6), [{scientific, 5}]),
    "1.53123e-06" = erlang:float_to_list(minimum(StateX6), [{scientific, 5}]),
    true = (count(StateX6) =:= count(StateM6A)) andalso
           (count(StateM6A) =:= count(StateM6B)),
    true = (minimum(StateX6) =:= minimum(StateM6A)) andalso
           (minimum(StateM6A) =:= minimum(StateM6B)),
    true = (maximum(StateX6) =:= maximum(StateM6A)) andalso
           (maximum(StateM6A) =:= maximum(StateM6B)),
    "5.000021791129e-01" = erlang:float_to_list(mean(StateX6),
                                                [{scientific, 12}]),
    "5.000021791129e-01" = erlang:float_to_list(mean(StateM6A),
                                                [{scientific, 12}]),
    "5.000021791129e-01" = erlang:float_to_list(mean(StateM6B),
                                                [{scientific, 12}]),
    "2.886061744484e-01" = erlang:float_to_list(uncache_stddev(StateX6),
                                                [{scientific, 12}]),
    "2.886061744484e-01" = erlang:float_to_list(uncache_stddev(StateM6A),
                                                [{scientific, 12}]),
    "2.886061744484e-01" = erlang:float_to_list(uncache_stddev(StateM6B),
                                                [{scientific, 12}]),
    "-6.7071408756e-04" = erlang:float_to_list(uncache_skewness(StateX6),
                                               [{scientific, 10}]),
    "-6.7071408756e-04" = erlang:float_to_list(uncache_skewness(StateM6A),
